pitfalls.badSnippet:
// Ignores display scaling; renders blurry on Retina screens
canvas.width = 300;
canvas.height = 300;

pitfalls.goodSnippet:
// Scales bitmap by devicePixelRatio while preserving layout dimensions
const dpr = window.devicePixelRatio || 1;
canvas.width = 300 * dpr;
canvas.height = 300 * dpr;
canvas.style.width = '300px';
canvas.style.height = '300px';
ctx.scale(dpr, dpr);
